"""Generated and vendored files that a default scan does not judge as app code.

A first scan of a Django project used to spend about a third of its findings on
two kinds of files nobody on the team wrote by hand:

* Django migrations (``<app>/migrations/0001_*.py``), generated by
  ``makemigrations``;
* third-party front-end code copied into the repository: libraries under a
  web root (``static/**/lib/**``, ``public/**/libs/**``, ``.../vendor/**``),
  ``*.min.js`` / ``*.min.css``, other minified JS/CSS (GitHub Linguist's
  rule: average line length above 110 characters) and files that open with a
  library licence banner (``/*! jQuery v3.6.1 | (c) OpenJS Foundation ... */``).

The CLI skips them by default and says so in one line; ``--include-generated``,
``--no-default-excludes``, ``[tool.skylos] include_generated = true``,
``--include-folder PATH`` or naming a file on the command line scans them.

A third kind is code a tool writes and marks as generated in its header
(``// Code generated ... DO NOT EDIT.``, ``@generated``, ``This file was
automatically generated by TanStack Router``, ``This file is auto-generated by
@hey-api/openapi-ts``). It is treated like a migration.

The kinds are skipped differently:

* Vendored files are removed from the scan, like the ``vendor`` default
  exclude. Nothing in app code depends on them being parsed.
* Migrations and generated sources are still parsed, so app code that only
  they use (a ``RunPython`` helper, a field validator, a component a
  generated route tree imports) is not reported as unused. Their
  dead-code, quality and AI-defect findings are not reported. Security and
  secret findings in migrations are kept: migrations run at deploy time with
  database credentials, so a path-based skip must not hide them.
"""

from __future__ import annotations

import os
import re
import stat
from collections.abc import Iterable, Sequence
from dataclasses import dataclass, field
from pathlib import Path

from skylos.core.file_discovery import exclusion_matcher

REASON_DJANGO_MIGRATION = "django_migration"
REASON_STATIC_LIB = "vendored_static_lib"
REASON_MINIFIED = "minified"
REASON_VENDORED_BANNER = "vendored_banner"
REASON_GENERATED_SOURCE = "generated_source"

# Parsed so their references count, but their dead-code, quality and
# AI-defect findings are not reported (security findings are kept).
REPORT_ONLY_REASONS = frozenset({REASON_DJANGO_MIGRATION, REASON_GENERATED_SOURCE})

# Result sections whose findings are not reported for migrations. Security,
# reliability, secret and custom-rule findings are kept (module docstring).
REPORT_ONLY_DROPPED_SECTIONS = (
    "unused_functions",
    "unused_imports",
    "unused_classes",
    "unused_variables",
    "unused_parameters",
    "unused_files",
    "unused_exports",
    "quality",
    "ai_defects",
)

_MINIFIED_SUFFIXES = (".min.js", ".min.mjs", ".min.cjs", ".min.css")
_FRONTEND_SUFFIXES = (".js", ".mjs", ".cjs", ".jsx", ".css")
_GENERATED_SOURCE_SUFFIXES = (
    ".py",
    ".ts",
    ".tsx",
    ".mts",
    ".cts",
    ".js",
    ".jsx",
    ".mjs",
    ".cjs",
    ".go",
    ".java",
    ".kt",
    ".cs",
    ".dart",
    ".rs",
)
# Generator markers in a file's leading comment block. Each names the file as
# generated (or carries the Go/Meta "DO NOT EDIT"/@generated convention); a
# comment that merely mentions generated values elsewhere does not match.
_GENERATED_HEADER_RE = re.compile(
    r"@generated\b"
    r"|\bcode\s+generated\b[^\n]*\bdo\s+not\s+edit\b"
    r"|\bthis\s+(?:file|module|code)\s+(?:is|was|has\s+been)\s+"
    r"(?:auto(?:matically)?[-\s]?)?generated\b"
    r"|\bauto[-\s]?generated\s+(?:by|from|file|code|using|with)\b"
    r"|\bautomatically\s+generated\s+(?:by|from|file|code|using|with)\b"
    r"|\bgenerated\s+by\b[^\n]*\bdo\s+not\s+edit\b",
    re.IGNORECASE,
)
# Directories served as-is to browsers, and the folders inside them that hold
# copied third-party libraries (BookStack ``public/libs/tinymce``).
_WEB_ROOT_DIRS = ("static", "public")
_WEB_LIBRARY_DIRS = frozenset({"lib", "libs", "vendor", "vendors"})
# GitHub Linguist (``Generated#minified_files?``) treats a .js/.css file whose
# average line length exceeds 110 characters as minified. A one-line bundle
# without a ``.min`` suffix (caddy's testdata player, 157,790 characters) is
# machine output; tiny files are left alone.
_MINIFIED_AVERAGE_LINE_LENGTH = 110
_MINIFIED_MIN_BYTES = 1024
_MINIFIED_SAMPLE_BYTES = 65_536
_MAX_MIGRATION_BYTES = 4_000_000
_BANNER_BYTES = 2048

_DJANGO_DB_IMPORT_RE = re.compile(
    r"^[ \t]*(?:from[ \t]+django\.db(?:\.migrations)?[ \t]+import\b"
    r"|import[ \t]+django\.db\b)",
    re.MULTILINE,
)
_MIGRATION_CLASS_RE = re.compile(
    r"^class[ \t]+Migration[ \t]*\([ \t]*(?:[A-Za-z_][\w.]*\.)?Migration[ \t]*\)[ \t]*:",
    re.MULTILINE,
)
_BANNER_VERSION_RE = re.compile(r"\bv?\d+\.\d+(?:\.\d+)?\b")
_BANNER_LICENSE_RE = re.compile(
    r"@license|\blicen[sc]ed?\b|copyright|\(c\)|\u00a9",
    re.IGNORECASE,
)


@dataclass
class GeneratedFileScope:
    """Files a scan skips as generated or vendored, with the reason for each."""

    root: Path
    excluded: dict[Path, str] = field(default_factory=dict)
    report_only: dict[Path, str] = field(default_factory=dict)

    @property
    def count(self) -> int:
        return len(self.excluded) + len(self.report_only)

    def report_only_keys(self) -> frozenset[str]:
        return frozenset(_path_keys(self.report_only))

    def summary(self) -> dict:
        by_reason: dict[str, list[str]] = {}
        for path, reason in (*self.report_only.items(), *self.excluded.items()):
            by_reason.setdefault(reason, []).append(_relative_text(path, self.root))
        return {
            "skipped_count": self.count,
            "by_reason": {
                reason: len(paths) for reason, paths in sorted(by_reason.items())
            },
            "files": {
                reason: sorted(paths) for reason, paths in sorted(by_reason.items())
            },
            "include_with": "--include-generated",
        }


def classify_generated_file(path: Path, root: Path) -> str | None:
    """Return why ``path`` is generated or vendored code, or ``None``.

    Path rules match only the part of the path below ``root`` (the directory
    being scanned), so pointing the scan at ``app/migrations`` scans it.
    """
    name = path.name.lower()
    try:
        rel_parts = path.relative_to(root).parts
    except ValueError:
        rel_parts = (path.name,)
    directories = [part.lower() for part in rel_parts[:-1]]

    if name.endswith(".py"):
        if (
            directories
            and directories[-1] == "migrations"
            and _is_django_migration(path)
        ):
            return REASON_DJANGO_MIGRATION
        return REASON_GENERATED_SOURCE if _has_generated_header(path) else None

    if name.endswith(_FRONTEND_SUFFIXES):
        for web_root in _WEB_ROOT_DIRS:
            if web_root in directories:
                root_at = directories.index(web_root)
                if _WEB_LIBRARY_DIRS.intersection(directories[root_at + 1 :]):
                    return REASON_STATIC_LIB
        if name.endswith(_MINIFIED_SUFFIXES):
            return REASON_MINIFIED
        if _has_vendored_banner(path):
            return REASON_VENDORED_BANNER
        if _looks_minified(path):
            return REASON_MINIFIED
    if name.endswith(_GENERATED_SOURCE_SUFFIXES) and _has_generated_header(path):
        return REASON_GENERATED_SOURCE
    return None


def partition_generated_files(
    files: Sequence[Path],
    root: Path,
    *,
    keep_paths: Iterable[str] | None = None,
    explicit_files: Iterable[Path] = (),
) -> tuple[list[Path], GeneratedFileScope]:
    """Split discovered ``files`` into analyzed files and a skip record.

    Returns the files to analyze (migrations included, vendored files
    removed) and the :class:`GeneratedFileScope` describing what was skipped.
    ``keep_paths`` are ``--include-folder`` style patterns; ``explicit_files``
    are files named on the command line. Neither is ever skipped.
    """
    root = Path(root)
    scope = GeneratedFileScope(root=root)
    keep = list(keep_paths or ())
    kept_by_pattern = exclusion_matcher(root, keep) if keep else None
    explicit = set(_path_keys(explicit_files))
    analyzed: list[Path] = []
    for file_path in files:
        path = Path(file_path)
        reason = None
        named = bool(explicit) and not explicit.isdisjoint(_path_keys((path,)))
        if not named and not (kept_by_pattern is not None and kept_by_pattern(path)):
            reason = classify_generated_file(path, root)
        if reason in REPORT_ONLY_REASONS:
            scope.report_only[path] = reason
            analyzed.append(file_path)
        elif reason is not None:
            scope.excluded[path] = reason
        else:
            analyzed.append(file_path)
    return analyzed, scope


def finding_in_files(finding, file_keys: frozenset[str]) -> bool:
    if not isinstance(finding, dict) or not file_keys:
        return False
    value = finding.get("file") or finding.get("filename") or finding.get("file_path")
    if not value:
        return False
    if str(value) in file_keys:
        return True
    return not file_keys.isdisjoint(_path_keys((value,)))


def _is_django_migration(path: Path) -> bool:
    if not (path.parent / "__init__.py").is_file():
        return False
    text = _read_text(path, _MAX_MIGRATION_BYTES)
    if text is None:
        return False
    return bool(_MIGRATION_CLASS_RE.search(text) and _DJANGO_DB_IMPORT_RE.search(text))


def _has_vendored_banner(path: Path) -> bool:
    head = _read_text(path, _BANNER_BYTES)
    if not head:
        return False
    comment = _leading_comment(head)
    if not comment:
        return False
    # "/*!" and @license/@preserve are the conventions minifiers keep for
    # licence banners; a version alone or a copyright line alone is not enough.
    preserved = (
        comment.startswith("/*!") or "@license" in comment or "@preserve" in comment
    )
    return bool(
        preserved
        and _BANNER_VERSION_RE.search(comment)
        and _BANNER_LICENSE_RE.search(comment)
    )


def _looks_minified(path: Path) -> bool:
    text = _read_text(path, _MINIFIED_SAMPLE_BYTES)
    if not text or len(text) < _MINIFIED_MIN_BYTES:
        return False
    lines = text.splitlines()
    return bool(lines) and (
        sum(len(line) for line in lines) / len(lines) > _MINIFIED_AVERAGE_LINE_LENGTH
    )


def _leading_comment(text: str) -> str | None:
    text = text.lstrip("\ufeff").lstrip()
    if text.startswith("/*"):
        end = text.find("*/")
        return text if end == -1 else text[: end + 2]
    if text.startswith("//"):
        lines = []
        for line in text.splitlines():
            if not line.lstrip().startswith("//"):
                break
            lines.append(line)
        return "\n".join(lines)
    return None


def _header_comments(text: str) -> str:
    """Comment lines before the first code line (``//``, ``/* */``, ``#``).

    Blank lines and lint pragmas between comments are part of the header:
    TanStack Router writes ``/* eslint-disable */`` and ``// @ts-nocheck``
    before its "automatically generated" line.
    """
    comments = []
    in_block = False
    for raw in text.lstrip("\ufeff").splitlines():
        line = raw.strip()
        if in_block:
            comments.append(line)
            if "*/" in line:
                in_block = False
            continue
        if not line:
            continue
        if line.startswith(("//", "#")):
            comments.append(line)
            continue
        if line.startswith("/*"):
            comments.append(line)
            in_block = "*/" not in line[2:]
            continue
        break
    return "\n".join(comments)


def _has_generated_header(path: Path) -> bool:
    head = _read_text(path, _BANNER_BYTES)
    if not head:
        return False
    return bool(_GENERATED_HEADER_RE.search(_header_comments(head)))


def _read_text(path: Path, max_bytes: int) -> str | None:
    """Up to ``max_bytes`` of a regular file, never through a symlink.

    ``path`` comes from source discovery (already contained in the scan root);
    only a prefix is needed to recognise a generated file.
    """
    flags = os.O_RDONLY
    for name in ("O_NOFOLLOW", "O_NONBLOCK", "O_CLOEXEC"):
        flags |= getattr(os, name, 0)
    try:
        fd = os.open(  # skylos: ignore[SKY-D215,SKY-D325] discovered in-root source file; no-follow, regular-file, bounded read
            path, flags
        )
    except OSError:
        return None
    try:
        if not stat.S_ISREG(os.fstat(fd).st_mode):
            return None
        chunks = []
        remaining = max_bytes
        while remaining > 0:
            chunk = os.read(fd, min(remaining, 65536))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
    except OSError:
        return None
    finally:
        os.close(fd)
    return b"".join(chunks).decode("utf-8", errors="ignore")


def _path_keys(paths) -> list[str]:
    keys = []
    for value in paths:
        text = str(value)
        keys.append(text)
        try:
            resolved = str(Path(text).resolve())
        except (OSError, RuntimeError, ValueError):
            continue
        if resolved != text:
            keys.append(resolved)
    return keys


def _relative_text(path: Path, root: Path) -> str:
    try:
        return path.relative_to(root).as_posix()
    except ValueError:
        return path.as_posix()
